let c = (await tools.read({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1960QPilotAnchorActual.lean" })).lines.map(l=>l.text).join("\n");
c = c.replace(
`canonical times-mu lift of the \`(1,0)\` core is the only actual candidate (it
is the term \`qPilotFTimesMuPrimeStripAt10\` of
\`QPilotFTimesMuPrimeStripActual\`); that module states explicitly that it is
not asserted to be the paper's q-pilot strip.`,
`named actual candidate is the canonical times-mu lift of the \`(1,0)\` core
(the term \`qPilotFTimesMuPrimeStripAt10\` of
\`QPilotFTimesMuPrimeStripActual\`); that module states explicitly that it is
not asserted to be the paper's q-pilot strip.`);
// insert square ties after reducedQPilotAnchor_eq_origXiF
const anchorMark = `/-- The reduced anchor is the OrigXiF actual source q-pilot strip at \`(1,0)\`. -/
@[simp] theorem reducedQPilotAnchor_eq_origXiF (D : S1895PaperInput) :
    reducedQPilotAnchor D = OrigXiFPaperStrip (paperInput D) 1 0 := rfl
`;
const insert = anchorMark + `
/-- The reduced anchor is the LGP (lower-left) corner of the actual
Kummer-evaluation square \`s1927Square D\` carried by the S1927 package. -/
@[simp] theorem reducedQPilotAnchor_eq_lgpStrip (D : S1895PaperInput) :
    reducedQPilotAnchor D = lgpStrip D := rfl

/-- The reduced anchor is the lower-left vertex of the package's actual
Kummer-evaluation square. -/
@[simp] theorem reducedQPilotAnchor_eq_packageSquare_lowerLeft
    (D : S1895PaperInput) :
    reducedQPilotAnchor D = (paperFullLogKummerUQ D).evaluationSquare.lowerLeft :=
  rfl
`;
if (!c.includes(anchorMark)) throw new Error("anchor mark not found");
c = c.replace(anchorMark, insert);
// add axiom probe for the square tie
c = c.replace("#print axioms s1960QPilotAnchoredUQ_label",
  "#print axioms s1960QPilotAnchoredUQ_label\n#print axioms reducedQPilotAnchor_eq_packageSquare_lowerLeft");
await tools.write({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1960QPilotAnchorActual.lean", content: c });
console.log("edited; bytes", c.length);
const r = await tools.pwsh({ description: "Recompile S1960 after edits", command: "lake env lean tmp/sheaf/xif/paper/S1960QPilotAnchorActual.lean 2>&1 | Tee-Object -FilePath tmp/sheaf/xif/paper/S1960.compile.log | Out-String; \"EXIT=$LASTEXITCODE\"", workdir: "D:\\lean", timeoutMs: 900000 });
console.log(r.kind === "foreground" ? r.stdout.text + "\nSTDERR:\n" + r.stderr.text : JSON.stringify(r));
", "description": "Add square ties and recompile"}

